"""Refresh the checked-in OpenAPI contract from the current FastAPI routes."""

from pathlib import Path

import yaml
from cmp_api.main import app

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "docs" / "contracts" / "openapi.yaml"
OUTPUT.write_text(
    "# Generated by `make openapi`; do not edit by hand.\n"
    + yaml.safe_dump(app.openapi(), allow_unicode=True, sort_keys=False),
    encoding="utf-8",
)
print(OUTPUT)
